local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/NIcoGabrielRealYtr/Ather-Hub-Library/refs/heads/main/Source"))()

local Window = Library:Window({
    Name = '<font color="rgb(175, 102, 126)">ather.</font>hub',
    Logo = "rbxassetid://133425623304338"
})

local Combat = Window:Page({
    Name = "Combat",
    Description = "Combat features",
    Icon = "lucide:sword",
    Search = true
})

local Visuals = Window:Page({
    Name = "Visuals",
    Description = "Visual enhancements",
    Icon = "lucide:eye"
})

local AimbotSub = Combat:SubPage({
    Name = "Aimbot",
    Icon = "lucide:target",
    DisplayName = true
})

local ESPSub = Visuals:SubPage({
    Name = "ESP",
    Icon = "lucide:eye",
    DisplayName = true
})

local MainSection = AimbotSub:Section({
    Name = "Main Settings",
    Side = 1
})

local VisualSection = ESPSub:Section({
    Name = "Visual Options",
    Side = 1
})

local aimbotToggle = MainSection:Toggle({
    Name = "Enable Aimbot",
    Flag = "AimbotEnabled",
    Default = false,
    Callback = function(Value)
        print("Aimbot:", Value)
    end
})

aimbotToggle:Keybind({
    Flag = "AimbotKeybind",
    Default = Enum.KeyCode.RightShift,
    Mode = "Toggle",
    Callback = function()
        print("Keybind pressed")
    end
})

aimbotToggle:Colorpicker({
    Flag = "AimbotColor",
    Default = Color3.fromRGB(255, 0, 0),
    Alpha = 0.5,
    Callback = function(Color, Alpha)
        print("Color set:", Color)
    end
})

MainSection:Button({
    Name = "Test Notification",
    Callback = function()
        Window:Notify({
            Title = "Test",
            Description = "Button clicked!",
            Duration = 3
        })
    end
})

MainSection:Slider({
    Name = "Aimbot FOV",
    Flag = "AimbotFOV",
    Default = 50,
    Min = 0,
    Max = 360,
    Decimals = 0,
    Suffix = "°",
    Callback = function(Value)
        print("FOV:", Value)
    end
})

MainSection:Dropdown({
    Name = "Target Priority",
    Flag = "TargetPriority",
    Items = {"Closest", "Lowest HP", "Distance"},
    Default = "Closest",
    Callback = function(Value)
        print("Priority:", Value)
    end
})

-- Multi-select dropdown
MainSection:Dropdown({
    Name = "Filters",
    Flag = "Filters",
